import React from "react";
import "./AdPage.css";

const AdPage = () => {
  return (
    <div className="ad-page-container">
      {/* Top Ad Banner */}
      <div className="ad-banner">
        <img src="/assets/ad-banner.jpg" alt="Ad Banner" />
      </div>

      {/* Products/Brands Section */}
      <div className="card-section">
        {[...Array(8)].map((_, i) => (
          <div className="card" key={i}>
            <img src="/assets/product.png" alt="Product" />
            <h3>Product {i + 1}</h3>
            <p>Brand Name</p>
            <button>Explore</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdPage;
